const fs = require('fs');

class Scanner {
    constructor() {
        this.buffer = [];
        this.input = fs.readFileSync(0, 'utf8').split(/\s+/).reverse();
    }
    next() {
        if (this.buffer.length === 0) {
            if (this.input.length === 0) {
                throw new Error("No more input");
            }
            this.buffer.push(this.input.pop());
        }
        return this.buffer.pop();
    }
}

function main() {
    const scan = new Scanner();
    const n = 4;
    let p = [];
    for (let i = 0; i < n; i++) {
        p.push(BigInt(scan.next()));
    }
    p.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    let dedup = [];
    for (let i = 0; i < p.length; i++) {
        if (i === 0 || p[i] !== p[i - 1]) {
            dedup.push(p[i]);
        }
    }
    process.stdout.write(String(n - dedup.length) + '\n');
}

main();

